import{_ as a,o as t,c as r,a4 as i}from"./chunks/framework.CzJ_HCFe.js";const p=JSON.parse('{"title":"Surgery Source Profile","description":"","frontmatter":{},"headers":[],"relativePath":"reference/27-surgery-profile.md","filePath":"reference/27-surgery-profile.md","lastUpdated":1788532705000}'),n={name:"reference/27-surgery-profile.md"};function o(s,e,h,c,d,l){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="surgery-source-profile" tabindex="-1">Surgery Source Profile <a class="header-anchor" href="#surgery-source-profile" aria-label="Permalink to &quot;Surgery Source Profile&quot;">​</a></h1><h2 id="safety-boundary" tabindex="-1">Safety boundary <a class="header-anchor" href="#safety-boundary" aria-label="Permalink to &quot;Safety boundary&quot;">​</a></h2><p>Muhurtam is never a reason to postpone urgent, necessary, or clinician-directed medical care. The treating clinician&#39;s instructions and the patient&#39;s medical needs always take priority. This boundary is published with the activity&#39;s manual checks, not left only in documentation.</p><h2 id="claim-and-authority" tabindex="-1">Claim and authority <a class="header-anchor" href="#claim-and-authority" aria-label="Permalink to &quot;Claim and authority&quot;">​</a></h2><p>The <code>surgery</code> activity is linked to <code>muhurta.surgery</code>. Its electional authority is B. V. Raman&#39;s <em>Muhurtha</em>, Chapter XV, &quot;Surgical Operations,&quot; printed pages 64-65 (PDF pages 68-69 in the registered edition). Raman is a modern secondary authority, not scripture or medical authority.</p><p>The passage recommends Tuesday or Saturday during Chandra&#39;s increase, rejects the exact full Moon, and names Chaturthi, Navami or Chaturdashi with Ardra, Jyeshtha, Ashlesha or Moola. The profile conservatively represents the waxing condition as the three corresponding Shukla Tithis.</p><h2 id="chart-level-conditions" tabindex="-1">Chart-level conditions <a class="header-anchor" href="#chart-level-conditions" aria-label="Permalink to &quot;Chart-level conditions&quot;">​</a></h2><p>The source also says to avoid Chandra in the patient&#39;s natal Rasi and the Rasi governing the operated body part, particularly under malefic affliction. It calls for strong Mangala and a strong relevant house, a vacant 8th house, and no mutual Mangala-Shani aspect.</p><p>When a patient is selected, the Drik browser rejects Chandra in that person&#39;s Janma Rashi at any sampled state. It also rejects a candidate whose eighth house is occupied at any sampled state. Samples cover the window edges and both sides of every known interior Drik Lagna transition. The operated-body-part Rashi, malefic affliction, strength and Mangala-Shani aspect model remain visible practitioner checks. Python/MCP do not call the chart service. See <a href="./54-muhurtam-election-chart-screening">Muhurtam election-chart screening</a>.</p><p>The existing Vishti-Karana rejection has separate project provenance and does not inherit authority from this passage. Python and MCP publish the stable claim ID, exact automated gates, safety boundary, and chart checks.</p>',10)])])}const y=a(n,[["render",o]]);export{p as __pageData,y as default};
